'use strict';
/**
 * Design system (v0.23): generic interface icons come from Lucide (ISC, already bundled as
 * extension/assets/icons/lucide.json — see tools/build-icons.js), so search / trash / settings …
 * look like one family. MOE keeps its own drawings only for motion ideas Lucide has no word for
 * (ease, loops, align, rigs …). This script copies the mapped icons into a small generated module:
 *
 *   node tools/build-ui-icons.js      → extension/app/ui/icons-ui.js (do not edit by hand)
 *
 * Map: MOE icon name → Lucide name. Lucide draws on a 24 grid; dom.icon() renders these with
 * viewBox 24 and a stroke of 2.25 so they match MOE's 16-grid icons at 1.5 px.
 */
const fs = require('fs');
const path = require('path');

const MAP = {
  search: 'search', trash: 'trash', gear: 'settings', history: 'rotate-ccw-clock', refresh: 'refresh-cw',
  chev: 'chevron-right', undo: 'undo-2', play: 'play', plus: 'plus', x: 'x', check: 'check', copy: 'copy',
  save: 'save', eye: 'eye', eyeOff: 'eye-off', lock: 'lock', folder: 'folder', star: 'star', upload: 'upload',
  download: 'download', import: 'import', info: 'info', keyboard: 'keyboard', gift: 'gift', sun: 'sun',
  moon: 'moon', heart: 'heart', filter: 'funnel', home: 'house', layers: 'layers', bolt: 'zap', tools: 'wrench',
  sparkles: 'sparkles', wand: 'wand-sparkles', crown: 'crown', lightbulb: 'lightbulb', clock: 'clock',
  link: 'link', gThirds: 'grid-3x3', gGolden: 'ratio', gCols: 'columns-4', gTv: 'tv', gMargin: 'square-dashed', gClear: 'eraser', gTiktok: 'eighth-note', gReels: 'clapperboard', gShorts: 'circle-play', gStories: 'circle-dashed', gPhone: 'smartphone', drop: 'droplet', palette: 'palette', type: 'type', target: 'crosshair', cursor: 'mouse-pointer-2',
  edit: 'pencil', sliders: 'sliders-horizontal', menu: 'menu', grip: 'grip-vertical', repeat: 'repeat',
  dots: 'ellipsis', code: 'code', expr: 'braces', zoom: 'zoom-in', contrast: 'contrast', presets: 'bookmark',
  pulse: 'activity', layout: 'layout-template',
  // v0.30.1 Ease Copy (the old paste icon read as a bin)
  easeCopy: 'clipboard-copy', easePaste: 'clipboard-paste'
};

const SRC = path.join(__dirname, '..', 'extension', 'assets', 'icons', 'lucide.json');
const OUT = path.join(__dirname, '..', 'extension', 'app', 'ui', 'icons-ui.js');

const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
function svgInner(nodes) { return nodes.map(([tag, attrs]) => `<${tag} ${Object.entries(attrs).filter(([k]) => k !== 'key').map(([k, v]) => `${k}="${esc(v)}"`).join(' ')}/>`).join(''); }

function build() {
  const lib = JSON.parse(fs.readFileSync(SRC, 'utf8'));
  const out = {};
  const missing = [];
  for (const [moe, lu] of Object.entries(MAP)) { const ic = lib.icons[lu]; if (!ic) missing.push(`${moe} → ${lu}`); else out[moe] = svgInner(ic.n); }
  if (missing.length) throw new Error(`Lucide ${lib.version} has no: ${missing.join(', ')}`);
  const body = Object.keys(out).sort().map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(out[k])}`).join(',\n');
  const text = `'use strict';\n/* GENERATED by tools/build-ui-icons.js from Lucide ${lib.version} (ISC, assets/icons/LICENSE-lucide.txt) — do not edit. 24-grid icons. */\nmodule.exports = {\n${body}\n};\n`;
  fs.writeFileSync(OUT, text);
  return { count: Object.keys(out).length, version: lib.version };
}

if (require.main === module) { const r = build(); console.log(`icons-ui.js: ${r.count} icons from Lucide ${r.version}`); }
module.exports = { MAP, build };
